  const S = await import('/src/engine/level/LevelStorage.js');
  const out = {};
  for (const [name, campaign] of [['emberfall', ''], ['starfall-vale', ''], ['brightwater-crossing', ''], ['mill-road', 'ferrymans-lantern'], ['millbrook', 'ferrymans-lantern'], ['millbrook-dusk', 'ferrymans-lantern']]) {
    const path = campaign ? `/campaigns/${campaign}/levels/` : '/levels/';
    const text = await fetch(`${path}${name}.json`, { cache: 'no-store' }).then((r) => r.text());
    await E.app.openProject(name, { confirm: false, campaign });
    // one object of each type through the inspector (its fields render; nothing may be written)
    const seen = new Set();
    for (const o of st.level.objects) { if (seen.has(o.type)) continue; seen.add(o.type); st.select([o.id]); E.app.inspector.render(); }
    st.clearSelection();
    await E.app._saveTo('project', 'zz-story-rt', { campaign });
    const saved = await fetch(`${path}zz-story-rt.json`, { cache: 'no-store' }).then((r) => r.text());
    out[name] = { same: saved === text, types: seen.size, dirty: st.dirty, undo: st.canUndo };
    SS.ok(saved === text && !st.canUndo, `${name}: saved unchanged → the same bytes`);
  }
  await S.deleteProjectLevel('zz-story-rt');
  await S.deleteProjectLevel('zz-story-rt', { campaign: 'ferrymans-lantern' });
  const left = [...(await S.listProjectLevels()).map((l) => l.name), ...(await S.listProjectLevels({ campaign: 'ferrymans-lantern' })).map((l) => l.name)].filter((n) => n.startsWith('zz-'));
  SS.ok(!left.length, 'the temporary files are deleted');
  st.setView({ layout: 'split' });
  return JSON.stringify({ out, left });
})()
